function routeIncoming(message, pending, notificationHandlers) {
  if (!("id" in message)) {
    const handler = notificationHandlers[message.method];
    if (handler) handler(message.params);
    return;
  }
  const entry = pending.get(message.id);
  if (entry && "result" in message) entry.resolve(message.result);
  if (entry && "error" in message) entry.reject(message.error);
  pending.delete(message.id);
}
